import{_ as s,h as a,o as n,aa as e}from"./chunks/framework.BsAE-16a.js";const m=JSON.parse('{"title":"spec-kit cursor实践","description":"","frontmatter":{},"headers":[],"relativePath":"daily-notes/issue-28.md","filePath":"daily-notes/issue-28.md","lastUpdated":null}'),p={name:"daily-notes/issue-28.md"},l=e(`<h1 id="spec-kit-cursor实践" tabindex="-1">spec-kit cursor实践 <a class="header-anchor" href="#spec-kit-cursor实践" aria-label="Permalink to &quot;spec-kit cursor实践&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">原文地址</p><p><a href="https://github.com/wild2life/daily-notes/issues/28" target="_blank" rel="noreferrer">spec-kit cursor实践 | GitHub</a></p></div><p>下载spec-kit</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>uv tool install specify-cli --from git+https://github.com/github/spec-kit.git</span></span>
<span class="line"><span>specify init &lt;PROJECT_NAME&gt;</span></span>
<span class="line"><span>specify check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>直接下载文件（推荐） 从 <a href="https://github.com/github/spec-kit/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 页面直接下载可执行文件。</p><p><a href="https://github.com/github/spec-kit/blob/main/spec-driven.md" target="_blank" rel="noreferrer">SSD详细介绍</a></p><ul><li>意图驱动开发 -- 先定义规范（做什么），再实现细节（如何做）</li><li>使用护栏和组织原则 创建丰富的规范</li><li>多步细分 -- 而不是根据提示词一次性生成代码</li><li>严重依赖AI</li></ul><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><h3 id="_1-constitution-项目宪章" tabindex="-1">1. <code>/constitution</code> - 项目宪章 <a class="header-anchor" href="#_1-constitution-项目宪章" aria-label="Permalink to &quot;1. \`/constitution\` -  项目宪章&quot;">​</a></h3><blockquote><p>作用：建立项目“宪章”，明确必须遵守的最高原则</p></blockquote><h4 id="内容" tabindex="-1">内容： <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容：&quot;">​</a></h4><ul><li>代码质量（如必须通过lint和单测）</li><li>测试标准（如TDD、覆盖率要求）</li><li>用户体验一致性（统一设计规范）</li><li>性能要求（如响应时间限制、资源占用指标） 避免AI在不同阶段给出互相矛盾或不符合规范的方案</li></ul><h4 id="示例场景" tabindex="-1">示例场景： <a class="header-anchor" href="#示例场景" aria-label="Permalink to &quot;示例场景：&quot;">​</a></h4><p>有初始化模板时：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>#speckit.constitution.md 克隆git@github.com:vbenjs/vue-vben-admin.git 作为脚手架，制定以代码质量、测试标准、用户体验一致性及性能要求为核心的原则。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>或使用现有仓库： 仓库clone单独clone下来,吧<code>.cursor</code> 和 <code>.spec</code>文件拖入，对应的命令也是有的</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>#speckit.constitution.md 当前仓库已有前端模版，严格遵守当前仓库的规则。制定以代码质量、测试标准、用户体验一致性及性能要求为核心的原则。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>无模板时：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>后端接口暂时nitropack mock服务，前端调用后端接口。前端使用Vue 3 + Vite，使用TypeScript 类型推断，使用 Pinia 进行全局状态管理，使用 Tailwind CSS，组件全部使用 Ant Design Vue,typescript严格模式，统一eslint和prettier，提交之前必须通过lint或者typecheck，所有页面功能都需附带单元测试和页面级e2e测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-specify-规格说明书" tabindex="-1">2. <code>/specify</code> - 规格说明书 <a class="header-anchor" href="#_2-specify-规格说明书" aria-label="Permalink to &quot;2. \`/specify\` - 规格说明书&quot;">​</a></h3><blockquote><p>作用：生成规格说明书，描述要实现的功能和目标。</p></blockquote><h4 id="内容-1" tabindex="-1">内容： <a class="header-anchor" href="#内容-1" aria-label="Permalink to &quot;内容：&quot;">​</a></h4><ul><li>用户故事 User Stories</li><li>功能需求 Requirements</li><li>关键实体 Key Entities</li><li>成功标准 Success Criteria</li></ul><p>不需要说明任何技术细节 需要检查spec.md文档，实现补充 每次执行都会创建一个feature分支</p><h4 id="示例场景-1" tabindex="-1">示例场景 <a class="header-anchor" href="#示例场景-1" aria-label="Permalink to &quot;示例场景&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>#speckit.specify.md 我要创建一个名字为EDI的后台管理项目，用于管理数据。用户登录之后进入首页。用户可以查看表格数据，表单输入关键词进入快捷搜索，支持导入和导出数据。</span></span>
<span class="line"><span>页面1：物料主数据</span></span>
<span class="line"><span>菜单结构：生产质量/生产质量数据/物料主数据</span></span>
<span class="line"><span>VueRouter定义：manufacture/baseData/supplier_pro_material_data</span></span>
<span class="line"><span>搜索表单如下：其中select就是select组件，默认为input</span></span>
<span class="line"><span>事业部（select）、供应商（select）、供应商名称、奇瑞零件名称、供应商总成零件名称、项目名称、工厂名称、芯片MPN标识名称</span></span>
<span class="line"><span>表格展示字段如下:</span></span>
<span class="line"><span>奇瑞零件号、奇瑞零件名称、事业部编号、事业部、供应商代码、供应商名称、供应商总成零件号、供应商总成零件名称、奇瑞硬件版本号、奇瑞软件版本号、车型、项目名称、是否SOP、数据同步执行时间、工厂代码、工厂名称、供应商零件版本号、芯片采购类型、芯片MPN标识码、芯片MPN标识名称、数据来源、物料有效期（天）、类型、创建人登录账号、创建时间、更新人登录账号、更新时间</span></span>
<span class="line"><span>交互细节补充：</span></span>
<span class="line"><span>1. 表格的第一列都是checkbox, 前两列是固定定位，表格的上方都有导入，导出，删除的按钮。</span></span>
<span class="line"><span>  1. 导入</span></span>
<span class="line"><span>    1. 选择文件</span></span>
<span class="line"><span>    2. 下载模版</span></span>
<span class="line"><span>  2. 导出</span></span>
<span class="line"><span>    1. 点击导出会打开一个title为自定义导出的弹窗，里面可以操作导出的列，表格有三个表头，第一个是checkbox，第二个是属性名，第三个是表格列名。checkbox默认全选，直接提交则会导出所有的表格数据。</span></span>
<span class="line"><span>    2. 导出方式默认为全部，可以选择分页，需要设置导出的页大小和页码。</span></span>
<span class="line"><span>    3. 导出的文件名称默认是菜单的名称，比如BOM主数据，用户可以手动修改</span></span>
<span class="line"><span>  3. 删除</span></span>
<span class="line"><span>    1. 表格的第一列checkbox选择后删除按钮disabled为false，默认是true。</span></span>
<span class="line"><span>2. 搜索表单所有使用Datepicker组件的，都需要支持rangePresets（查看今天、近三天、近一周、近30天、近90天）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h3 id="_3-plan-技术实现计划" tabindex="-1">3. <code>/plan</code> - 技术实现计划 <a class="header-anchor" href="#_3-plan-技术实现计划" aria-label="Permalink to &quot;3. \`/plan\` - 技术实现计划&quot;">​</a></h3><blockquote><p>作用:制定技术实现计划</p></blockquote><h4 id="内容-2" tabindex="-1">内容 <a class="header-anchor" href="#内容-2" aria-label="Permalink to &quot;内容&quot;">​</a></h4><ul><li>技术栈（前端、后端、数据库、第三方服务）</li><li>架构设计（模块划分、交互方式）</li><li>API合约雏形（路径、 请求/响应格式）</li><li>数据模型设计（字段、关系）</li><li>外部依赖于集成点</li></ul><h4 id="示例场景-2" tabindex="-1">示例场景 <a class="header-anchor" href="#示例场景-2" aria-label="Permalink to &quot;示例场景&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>#speckit.plan.md 当前模版已经提供了技术选型Vue3+Composition API，UI库使用ant-design-vue。严格使用当前仓库的代码风格和规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>只能修改apps/下的文件代码。业务代码目录apps/web-antd，mock服务目录apps/backend-mock。</span></span>
<span class="line"><span>mock服务返回的格式 { code: 0, data: {}, message: &#39;&#39;},列表接口返回格式可以参考apps/backend-mock/api/table/list.ts文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>业务代码可以参考playground下面的文件，使用useVbenForm和useVbenGrid，代码风格也要参开playground下面的例子。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span></span></span>
<span class="line"><span>前端采用 Next.js 14 (App Router 模式)，结合 TailwindCSS 与 shadcn/ui 构建用户界面，应用的主要页面包括任务列表页、新建任务页和设置页。TailwindCSS 负责全局样式、shadcn/ui 提供按钮、菜单、对话框等基础交互组件。前端状态管理使用 React 状态与服务器组件数据获取结合。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后端使用 Supabase 提供数据库和认证服务，数据库表设计如下：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>users 表: id, email, created_at</span></span>
<span class="line"><span></span></span>
<span class="line"><span>todos 表: id, user_id, title, description, due_date, priority, completed, created_at, updated_at</span></span>
<span class="line"><span></span></span>
<span class="line"><span>认证由 Supabase Auth 完成，前端通过 session 获取用户信息，所有任务与用户 id 绑定。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数据获取采用 Next.js Server Actions 调用 Supabase，增加配置 todos 时，使用 Supabase 的 row-level security 策略，确保用户只能访问自己的任务。前端通过 React Server Components 获取任务列表，客户端交互（添加/编辑/完成任务）通过 form actions 或 client component 调用 API route。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>性能与安全要求：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所有接口需启用 HTTPS，敏感信息不写入前端代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>前端必须实现输入校验（zod），后端由 Supabase 约束与触发器保证数据一致性。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>页面初始加载目标在 1.5s 内，JS 首包控制在 120KB 内。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>非功能需求：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UI 必须具备可访问性（ally）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提供简单的移动通信适应布局。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所有新增任务必须可设置截止日期与优先级，并在任务到期当天通过前端提醒显示。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终交付：plan.md 会如何在本地运行（连接以及相关的性能要求之类的 POST /todos)，以及 quickstart 文档说明。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br></div></div><h3 id="_4-tasks-任务拆解" tabindex="-1">4. <code>/tasks</code> - 任务拆解 <a class="header-anchor" href="#_4-tasks-任务拆解" aria-label="Permalink to &quot;4. \`/tasks\` - 任务拆解&quot;">​</a></h3><p>将求拆解为具体的开发任务，生成 task.md 文件。</p><h3 id="_5-implement-实现落地" tabindex="-1">5. <code>/implement</code> - 实现落地 <a class="header-anchor" href="#_5-implement-实现落地" aria-label="Permalink to &quot;5. \`/implement\` - 实现落地&quot;">​</a></h3><p>执行具体的代码实现工作。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="拆解多个spec" tabindex="-1">拆解多个<code>spec</code> <a class="header-anchor" href="#拆解多个spec" aria-label="Permalink to &quot;拆解多个\`spec\`&quot;">​</a></h3><p>对于大型项目，建议拆分为多个 spec 文件分别管理。</p><h3 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to &quot;优缺点&quot;">​</a></h3><p>优点: 用一套框架对齐需求、减少遗漏 缺点: 对于写spec要求非常高 + 超级慢</p>`,42),i=[l];function r(c,t,o,b,u,d){return n(),a("div",null,i)}const k=s(p,[["render",r]]);export{m as __pageData,k as default};
